async function handlePaymentEvent(event) {
  const { eventId, accountId, amountCents } = event;

  return db.transaction(async (tx) => {
    // Try to claim this event ID. If it already exists, this insert
    // fails on the primary key and we know it is a duplicate delivery.
    const claimed = await tx.query(
      'INSERT INTO processed_events (event_id) VALUES ($1) ON CONFLICT DO NOTHING RETURNING event_id',
      [eventId]
    );

    if (claimed.rowCount === 0) {
      // Already processed once before. Safe to ignore this redelivery.
      console.log('duplicate event ignored', eventId);
      return;
    }

    // First time we have seen this event id, apply the charge for real.
    await tx.query(
      'UPDATE ledger SET balance = balance - $1 WHERE account_id = $2',
      [amountCents, accountId]
    );
  });
}

